# Verify review artifact references, including all nested sample paths.
paths=[]
def walk(x):
 if isinstance(x,dict):
  for k,v in x.items():
   if k in ('sample_refs','evidence_paths'):paths.extend(v)
   else:walk(v)
 elif isinstance(x,list):
  for v in x:walk(v)
walk(result);walk(load('pedagogical-variation.json'))
